from collections import Counter,defaultdict
import random,math,json
maxerr={'collision':0.0,'observed':0.0,'surrogate':0.0,'padding':0.0,'reverse':0.0,'diagonal':0.0,'upper_violation':0.0};cases=0

def summarize(events,target):
 table=defaultdict(Counter);valid=[]
 for c,b,a,age,mask in events:
  if not(mask and c>0 and b>0):continue
  g=int(b==target[1] and b>0)*2+int(c==target[0] and c>0)
  k=4*(a-1)+int(age>=3600)+int(age>=86400)+int(age>=604800)
  table[g,k][c,b]+=1;valid.append((g,k,c,b))
 n={cell:sum(v.values()) for cell,v in table.items()}
 cols={(g,k):sum(x*x for x in table[g,k].values())/max(n.get((g,k),0),1)**2 for g in range(4) for k in range(16)}
 G={};U={}
 for g in range(4):
  for i in range(16):
   for j in range(16):
    denom=max(n.get((g,i),0)*n.get((g,j),0),1)
    G[g,i,j]=sum(x*table[g,j].get(key,0) for key,x in table[g,i].items())/denom
    U[g,i,j]=math.sqrt(cols[g,i])*math.sqrt(cols[g,j])
 return cols,G,U,n,valid
for seed in range(24):
 rng=random.Random(seed)
 for length in [0,1,2,7,16,128]:
  events=[(rng.randrange(9),rng.randrange(11),rng.randrange(1,5),rng.choice([0,3599,3600,86399,86400,604799,604800,1000000]),rng.random()>.2) for _ in range(length)]
  for target in [(0,0),(2,3),(5,7)]:
   C,G,U,n,valid=summarize(events,target)
   # Independent event-equality multiplicity oracle, with all n*n pairs.
   oracle=Counter()
   for g,k,c,b in valid:
    for h,j,d,e in valid:
     if g==h and c==d and b==e:oracle[g,k,j]+=1
   for g in range(4):
    for i in range(16):
     for j in range(16):
      expected=oracle[g,i,j]/max(n.get((g,i),0)*n.get((g,j),0),1)
      maxerr['observed']=max(maxerr['observed'],abs(G[g,i,j]-expected))
      ci=oracle[g,i,i]/max(n.get((g,i),0)**2,1);cj=oracle[g,j,j]/max(n.get((g,j),0)**2,1)
      maxerr['surrogate']=max(maxerr['surrogate'],abs(U[g,i,j]-math.sqrt(ci*cj)))
      maxerr['upper_violation']=max(maxerr['upper_violation'],G[g,i,j]-U[g,i,j])
      if i==j:
       maxerr['collision']=max(maxerr['collision'],abs(C[g,i]-expected));maxerr['diagonal']=max(maxerr['diagonal'],abs(U[g,i,i]-C[g,i]))
      if n.get((g,i),0)==0 or n.get((g,j),0)==0:assert U[g,i,j]==0 and G[g,i,j]==0
   for label,altered in [('padding',events+[(8,10,4,604800,False)]*3),('reverse',list(reversed(events)))]:
    a=summarize(altered,target)
    for field in [1,2]:maxerr[label]=max(maxerr[label],max((abs(a[field][k]-v) for k,v in [G,U][field-1].items()),default=0))
   assert all(math.isfinite(x) and x>=0 for x in list(C.values())+list(G.values())+list(U.values()))
   assert max(G.values(),default=0)<=1+1e-12 and max(U.values(),default=0)<=1+1e-12
   assert not any(summarize([(c,b,a,t,False) for c,b,a,t,m in events],target)[2].values())
   cases+=1
# Mechanism witnesses in target-neither group, separate action contexts.
base=[(2,3,1,0,True),(2,3,2,0,True)];altered=[base[0],(4,5,2,0,True)]
_,g1,u1,_,_=summarize(base,(8,10));_,g2,u2,_,_=summarize(altered,(8,10))
assert g1[0,0,4]==1 and g2[0,0,4]==0 and u1[0,0,4]==u2[0,0,4]==1
assert all(v<1e-12 for v in maxerr.values()),maxerr
print(json.dumps({'standard_library_algebra_cases':cases,'maximum_float64_errors':maxerr,'witness':{'same_identity_overlap':g1[0,0,4],'disjoint_identity_overlap':g2[0,0,4],'both_concentration_surrogates':u1[0,0,4]},'scope':'independent scalar formula checks; no PyTorch, model training, utility or timings'},indent=2))
PY"

